# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: A derivative-free evolutionary strategy utilizing a Gaussian mutation operator with adaptive step sizing.
# Search state: Current best point found so far and the current global step size (sigma).
# Candidate generation: New candidates are generated by sampling from a multivariate normal distribution centered at the best point.
# Selection and replacement: Simple elitist selection; if a new candidate performs better than the existing best, it replaces it.
# Adaptation: A simple 1/5th success rule is used to adjust sigma: increase if success rate is high, decrease if low.
# Exploration mechanisms: Gaussian mutation with a dynamically adjusted standard deviation (step size).
# Exploitation mechanisms: Local refinement around the current best known solution.
# Boundary handling: Candidates generated outside boundaries are projected back to the nearest bound.
# Budget strategy: Exhaustive use of the set budget; termination occurs exactly when budget is depleted.
# Closest known influences: Evolutionary Strategy (ES) with (1+1)-selection and adaptive step-size control.
# Novelty or unusual aspects: Minimalist implementation of adaptive ES requiring no external dependencies.
# Failure modes: Susceptible to getting trapped in local optima in highly multi-modal landscapes.
# ALGORITHM_ANALYSIS_NOTE_END

import numpy as np

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        # Extract bounds
        if hasattr(func, 'lower') and hasattr(func, 'upper'):
            lb, ub = np.array(func.lower), np.array(func.upper)
        else:
            lb, ub = np.array(func.bounds.lb), np.array(func.bounds.ub)
        
        # Initial sampling
        best_x = np.random.uniform(lb, ub, self.dim)
        best_y = func(best_x)
        
        # Initial hyper-parameters for step size adaptation
        sigma = 0.2 * (ub - lb)
        eval_count = 1
        success_count = 0
        
        # Main optimization loop
        while eval_count < self.budget:
            # Generate candidate using Gaussian mutation
            candidate = best_x + np.random.normal(0, sigma)
            
            # Boundary constraint satisfaction (Projection)
            candidate = np.clip(candidate, lb, ub)
            
            # Evaluate
            current_y = func(candidate)
            eval_count += 1
            
            # Selection
            if current_y < best_y:
                best_y = current_y
                best_x = candidate
                success_count += 1
            
            # 1/5th success rule: Adapt sigma every 10 iterations
            if eval_count % 10 == 0:
                success_rate = success_count / 10
                if success_rate > 0.2:
                    sigma *= 1.25
                elif success_rate < 0.2:
                    sigma *= 0.8
                success_count = 0
                
        return best_x, best_y
